from pathlib import Path
import os,sys,json,subprocess,statistics,hashlib
sys.path.insert(0,'tests')
from perf import parse
r=Path(__file__).parent;out=r/'synthetic-perf';out.mkdir(exist_ok=False)
old=r.parent/'llmx-worker-errors'
arms={'control':old/'control.exe','checkpoint':old/'candidate.exe','candidate':r/'candidate.exe'}
rows=[]
(out/'metadata.json').write_text(json.dumps(dict(sha256={k:hashlib.sha256(v.read_bytes()).hexdigest() for k,v in arms.items()},rounds=9,outer_warmup=1,threads=6,prompt=64,decode=64),indent=2))
for pair in range(-1,9):
 order=list(arms); shift=(pair+1)%len(order); order=order[shift:]+order[:shift]
 for arm in order:
  cmd=[str(arms[arm]),'bench','--size','2048','--iters','10','--threads','6','--p','64','--n','64']
  p=subprocess.run(cmd,capture_output=True);(out/f'{pair}-{arm}.stdout').write_bytes(p.stdout);(out/f'{pair}-{arm}.stderr').write_bytes(p.stderr);p.check_returncode()
  row=dict(pair=pair,arm=arm,**parse(p.stdout.decode().splitlines()));rows.append(row)
  (out/'results.json').write_text(json.dumps(rows,indent=2));print(json.dumps(row),flush=True)
summary={}
for arm in arms:
 summary[arm]={}
 for key in ['matmul_gflops','prefill_tps','decode_tps']:
  values=[x[key] for x in rows if x['pair']>=0 and x['arm']==arm]
  summary[arm][key]=dict(mean=statistics.mean(values),minimum=min(values),maximum=max(values))
(out/'summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2),flush=True)

